import { useParams, useSearchParams } from 'react-router-dom';
import { useGetUserInfoQuery } from '~/entities/user/api/use-get-cstmr-query';
import { WalletHistoryDetailResponseDTO } from '~/entities/wallet/api/dtos/wallet-history-detail';
import {
  useWalletHistoryDetailQuery,
  WalletHistoryDetailParams,
} from '~/entities/wallet/api/use-wallet-history-detail-query';
import { CBDCAxiosError } from '~/shared/@types/error';
import { QueryOptions } from '~/shared/@types/query';
import { validateWalletData } from './validateWalletData';

type UseWalletHistoryDetailOptions = QueryOptions<WalletHistoryDetailResponseDTO, CBDCAxiosError> & {
  skipValidation?: boolean;
};

export const useWalletParams = () => {
  const { historyId } = useParams();
  const [searchParams] = useSearchParams();
  const { data: userRes } = useGetUserInfoQuery();
  const vouchId = searchParams.get('vouchId') ?? undefined;

  return {
    tbAcnutMastr: {
      acnutno: userRes?.tbCstmrMastr?.acnutno ?? '',
      trnscId: historyId ?? '',
      vouchId,
    },
  };
};

export const useWalletHistoryDetail = (params?: WalletHistoryDetailParams, options?: UseWalletHistoryDetailOptions) => {
  const _params = useWalletParams();

  const finalParams = params ?? _params;
  const { data } = useWalletHistoryDetailQuery(finalParams, {
    ...options,
  });

  // Use validateWalletData to validate and process the data
  // Pass the skipValidation option to control whether validation is performed
  const processedData = data ? validateWalletData(data, options?.skipValidation) : undefined;

  return {
    detailData: processedData,
  };
};
