import { z } from 'zod';
import { RefundSttus } from '~/shared/api/dtos/enums';
import { baseHistorySchema, numericString } from './base-history-schema';
import { voucherSchema, withVoucherValidation } from './voucher-schema';

export const paymentSchema = withVoucherValidation(
  baseHistorySchema
    .extend({
      fromInsttCd: z.string(),
      toInsttCd: z.string(),
      approvalCd: z.string(),
      refundSttus: z.nativeEnum(RefundSttus),
      refundCd: z.string().nullable().optional(),
      refundId: z.string().nullable().optional(),
      trnscId: z.string(),
      vouchTyCd: z.string(),
    })
    .merge(voucherSchema)
    .refine(
      (data) => {
        if (data.refundSttus === RefundSttus.환불완료) {
          return !!data.refundId;
        }
        return true;
      },
      {
        path: ['refundId'],
      },
    ),
);

export const refundSchema = withVoucherValidation(
  baseHistorySchema
    .extend({
      fromInsttCd: z.string(),
      refundAmt: numericString,
      refundDt: z.string(),
      refundCd: z.string().nullable().optional(),
      approvalCd: z.string(),
      refundVouchAmt: z.string().regex(/^\d+$/).nullable().optional(),
      vouchTyCd: z.string().nullable().optional(),
    })
    .merge(voucherSchema),
);

export const cashbackSchema = withVoucherValidation(
  baseHistorySchema
    .extend({
      cashbagAmt: numericString,
      cashbagCd: z.string(),
      walletDpstr: z.string(),
      amt: numericString,
      keyId: z.string(),
      trnscAfterBlce: z.string(),
    })
    .merge(voucherSchema),
);

export const vouchSchema = withVoucherValidation(
  baseHistorySchema
    .extend({
      cashbagAmt: numericString,
      cashbagCd: z.string(),
      walletDpstr: z.string(),
      amt: numericString,
      keyId: z.string().optional(),
      trnscAfterBlce: z.string(),
      refundSttus: z.nativeEnum(RefundSttus),
      refundCd: z.string().nullable().optional(),
    })
    .merge(voucherSchema),
);

export const remittanceSchema = baseHistorySchema.extend({
  aliasNm: z.string(),
  resWalletInsttNm: z.string().nullable().optional(),
  refundTransferId: z.string().nullable().optional(),
  ntsApprovalCd: z.string().optional(), // 현금영수증 승인번호 , 260109 추가
});

export const convertToTokenSchema = baseHistorySchema;
export const convertToDepositSchema = baseHistorySchema;
export const topUpSchema = baseHistorySchema;
export const conversionSchema = baseHistorySchema;

// codeName validation schema
export const withCodeNameSchema = <T extends z.ZodType>(schema: T) =>
  z.object({
    data: schema,
    codeName: z.string(),
  });
