import { z } from 'zod';
import { WalletHistoryDetailResponseDTO } from '~/entities/wallet/api/dtos/wallet-history-detail';
import { ValidationError } from './errors';
import { getSchemaByTransactionType } from './get-schema-by-transaction-type';
import { processWalletData } from './process-wallet-data';

export const validateWalletData = (data: WalletHistoryDetailResponseDTO, skipValidation?: boolean) => {
  const processedData = processWalletData(data);

  // If skipValidation is true, return the processed data without validation
  if (skipValidation) {
    return processedData;
  }

  try {
    const schema = getSchemaByTransactionType(processedData.trnscTypeCd ?? '');
    const validatedData = schema.parse(processedData);
    return validatedData;
  } catch (error) {
    if (error instanceof z.ZodError) {
      throw new ValidationError(
        'Validation Failed',
        error.errors.map((err) => ({
          field: err.path.join('.'),
          message: err.message,
        })),
      );
    }
    throw error;
  }
};
