import {
  paymentSchema,
  refundSchema,
  cashbackSchema,
  remittanceSchema,
  convertToTokenSchema,
  convertToDepositSchema,
  topUpSchema,
  conversionSchema,
  vouchSchema,
} from '~/entities/wallet/lib/schemas';
import { TrnscTypeCd } from '~/shared/api/dtos/enums';

export const getSchemaByTransactionType = (trnscTypeCd: string) => {
  switch (trnscTypeCd) {
    case TrnscTypeCd.송금:
    case TrnscTypeCd.환불송금:
      return remittanceSchema;
    case TrnscTypeCd.예금전환:
      return convertToDepositSchema;
    case TrnscTypeCd.전환입금:
      return convertToTokenSchema;
    case TrnscTypeCd.전환:
      return conversionSchema;
    case TrnscTypeCd.충전:
      return topUpSchema;
    case TrnscTypeCd.캐시백:
    case TrnscTypeCd.캐시백환불:
      return cashbackSchema;
    case TrnscTypeCd.보조금:
    case TrnscTypeCd.보조금환불:
      return vouchSchema;
    case TrnscTypeCd.결제:
    case TrnscTypeCd.온라인결제:
      return paymentSchema;
    case TrnscTypeCd.환불:
      return refundSchema;
    default:
      throw new Error(`Unknown transaction type: ${trnscTypeCd}`);
  }
};
